/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type FinanceChartProps = Record<string, any>;

const FinanceChart: React.FC<FinanceChartProps> = ({
  backgroundColor = "#0D1117",
  transparentBackground = false,
  durationInSeconds = 8,
  companyName = "Malloy Studio",
  downColor = "#F85149",
  upColor = "#2EA043",
  flatColor = "#8B949E",
  gridColor = "rgba(139, 148, 158, 0.2)",
  textColor = "#8B949E",
  lineWidth = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const totalFrames = durationInSeconds * fps;
  const startPadding = Math.floor(totalFrames * 0.1);
  const endPadding = Math.floor(totalFrames * 0.1);

  const startX = width * 0.1;
  const w = width * 0.8;
  const startY = height * 0.3;
  const h = height * 0.45;

  // Keyframes for the chart (x is percentage of width, p is price logic value)
  const chartPoints = [
    // Downward phase (Red)
    { x: 0.0, p: 150 },
    { x: 0.08, p: 142 },
    { x: 0.16, p: 146 },
    { x: 0.24, p: 110 },
    { x: 0.32, p: 105 },
    { x: 0.4, p: 90 },
    // Recovery phase (Green) - partial recovery
    { x: 0.47, p: 95 },
    { x: 0.54, p: 92 },
    { x: 0.61, p: 105 },
    { x: 0.7, p: 115 },
    // Plateau phase (Grey)
    { x: 0.8, p: 115 },
    { x: 0.9, p: 115 },
    { x: 1.0, p: 115 },
  ];

  const redPts = chartPoints.slice(0, 6);
  const greenPts = chartPoints.slice(5, 10);
  const greyPts = chartPoints.slice(9, 13);

  const getCoords = (pt: { x: number; p: number }) => {
    const x = startX + w * pt.x;
    // Map price 80-160 to Y bounds
    const y = startY + h * (1 - (pt.p - 80) / 80);
    return { x, y };
  };

  const toStrokePath = (pts: { x: number; p: number }[]) => {
    return pts
      .map((pt, i) => {
        const { x, y } = getCoords(pt);
        return `${i === 0 ? "M" : "L"} ${x} ${y}`;
      })
      .join(" ");
  };

  const toAreaPath = (pts: { x: number; p: number }[]) => {
    const stroke = toStrokePath(pts);
    const lastX = startX + w * pts[pts.length - 1].x;
    const firstX = startX + w * pts[0].x;
    const bottomY = startY + h;
    return `${stroke} L ${lastX} ${bottomY} L ${firstX} ${bottomY} Z`;
  };

  const drawProgress = interpolate(frame, [startPadding, totalFrames - endPadding], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Calculate current interpolated price and exact Y position
  let currentPtIndex = 0;
  for (let i = 0; i < chartPoints.length - 1; i++) {
    if (drawProgress >= chartPoints[i].x && drawProgress <= chartPoints[i + 1].x) {
      currentPtIndex = i;
      break;
    }
  }
  if (drawProgress >= 1) {
    currentPtIndex = chartPoints.length - 2;
  }

  const pt1 = chartPoints[currentPtIndex];
  const pt2 = chartPoints[currentPtIndex + 1];
  const segmentProgress = pt2.x === pt1.x ? 0 : (drawProgress - pt1.x) / (pt2.x - pt1.x);
  
  const currentLogicPrice = pt1.p + (pt2.p - pt1.p) * segmentProgress;
  const finalX = startX + w * drawProgress;
  const currentY = startY + h * (1 - (currentLogicPrice - 80) / 80);

  // Determine active color for dot
  let dotColor = downColor;
  if (drawProgress >= 0.4 && drawProgress < 0.7) {
    dotColor = upColor;
  } else if (drawProgress >= 0.7) {
    dotColor = flatColor;
  }

  const dotScale = spring({
    frame: frame - startPadding,
    fps,
    config: { damping: 12, mass: 0.5 },
  });

  // Data mapping for display
  const startPx = chartPoints[0].p * 100;
  const curPx = currentLogicPrice * 100;
  const diffPx = curPx - startPx;
  const pctChange = (diffPx / startPx) * 100;
  
  const isPositive = diffPx >= 0;
  const diffColor = isPositive ? upColor : diffPx < 0 ? downColor : flatColor;
  const sign = isPositive ? "+" : "";

  const gridLinesY = [0, 0.25, 0.5, 0.75, 1];
  const gridLinesX = [0, 0.2, 0.4, 0.6, 0.8, 1];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: spaceGrotesk, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          left: startX,
          display: "flex",
          flexDirection: "column",
          gap: 15,
          transition: "none",
        }}
      >
        <div style={{ fontSize: 36, color: textColor, textTransform: "uppercase", letterSpacing: 2 }}>
          {companyName}
        </div>
        <div style={{ display: "flex", alignItems: "flex-end", gap: 24, transition: "none" }}>
          <div style={{ fontSize: 110, fontWeight: "bold", color: "white", fontVariantNumeric: "tabular-nums", lineHeight: 1 }}>
            ${curPx.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </div>
          <div style={{ fontSize: 42, fontWeight: "bold", color: diffColor, marginBottom: 10, fontVariantNumeric: "tabular-nums" }}>
            {sign}{diffPx.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            &nbsp;({sign}{pctChange.toFixed(2)}%)
          </div>
        </div>
      </div>

      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}>
        <defs>
          <linearGradient id="gradient-red" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={downColor} stopOpacity="0.3" />
            <stop offset="100%" stopColor={downColor} stopOpacity="0" />
          </linearGradient>
          <linearGradient id="gradient-green" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={upColor} stopOpacity="0.3" />
            <stop offset="100%" stopColor={upColor} stopOpacity="0" />
          </linearGradient>
          <linearGradient id="gradient-grey" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={flatColor} stopOpacity="0.3" />
            <stop offset="100%" stopColor={flatColor} stopOpacity="0" />
          </linearGradient>
          
          <mask id="chart-mask">
            <rect 
              x={startX - 50} 
              y="0" 
              width={Math.max(0, w * drawProgress + 50)} 
              height={height} 
              fill="white" 
              style={{ transition: "none" }} 
            />
          </mask>
        </defs>

        <g id="grid">
          {gridLinesY.map((pct) => (
            <line
              key={`y-${pct}`}
              x1={startX}
              y1={startY + h * pct}
              x2={startX + w}
              y2={startY + h * pct}
              stroke={gridColor}
              strokeWidth={2}
              strokeDasharray="10 10"
            />
          ))}
          {gridLinesX.map((pct) => (
            <line
              key={`x-${pct}`}
              x1={startX + w * pct}
              y1={startY}
              x2={startX + w * pct}
              y2={startY + h}
              stroke={gridColor}
              strokeWidth={2}
              strokeDasharray="10 10"
            />
          ))}
        </g>

        <g mask="url(#chart-mask)">
          {/* Red Segment */}
          <path d={toAreaPath(redPts)} fill="url(#gradient-red)" />
          <path d={toStrokePath(redPts)} stroke={downColor} strokeWidth={lineWidth} fill="none" strokeLinecap="round" strokeLinejoin="round" style={{ filter: `drop-shadow(0px 0px 8px ${downColor})` }} />
          
          {/* Green Segment */}
          <path d={toAreaPath(greenPts)} fill="url(#gradient-green)" />
          <path d={toStrokePath(greenPts)} stroke={upColor} strokeWidth={lineWidth} fill="none" strokeLinecap="round" strokeLinejoin="round" style={{ filter: `drop-shadow(0px 0px 8px ${upColor})` }} />
          
          {/* Grey Segment */}
          <path d={toAreaPath(greyPts)} fill="url(#gradient-grey)" />
          <path d={toStrokePath(greyPts)} stroke={flatColor} strokeWidth={lineWidth} fill="none" strokeLinecap="round" strokeLinejoin="round" style={{ filter: `drop-shadow(0px 0px 8px ${flatColor})` }} />
        </g>

        {frame >= startPadding && (
          <g id="cursor" style={{ transform: `scale(${dotScale})`, transformOrigin: `${finalX}px ${currentY}px`, transition: "none" }}>
            <circle cx={finalX} cy={currentY} r={lineWidth} fill="white" />
            <circle cx={finalX} cy={currentY} r={lineWidth * 1.5} fill={dotColor} opacity={0.8} />
            <circle cx={finalX} cy={currentY} r={lineWidth * 3} fill={dotColor} opacity={0.3} />
          </g>
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default FinanceChart;